/** Generate the served setup page from design/glass-setup/template.html. */
import { readFileSync, writeFileSync } from "node:fs";

const html = readFileSync(new URL("../design/glass-setup/template.html", import.meta.url), "utf8");

if (process.argv.includes("--production")) {
  writeFileSync(new URL("../container/welcome.mjs", import.meta.url),
    "// Generated by npm run build:setup. Edit design/glass-setup/template.html or the renderer.\n" +
    "export const welcomePage = " + JSON.stringify(html) + ";\n");
  console.log("Generated container/welcome.mjs");
} else {
  const destination = new URL("../design/glass-setup/preview.html", import.meta.url);
  writeFileSync(destination, html);
  console.log(`Rendered ${destination.pathname}`);
}
